WITH page_sales AS (SELECT cp.cp_department AS department, cp.cp_catalog_page_id AS catalog_page_id, MIN(d_start.d_date) AS start_date, MAX(d_end.d_date) AS end_date, SUM(cs.cs_ext_sales_price) AS total_sales, SUM(cs.cs_net_profit) AS total_profit, AVG(cs.cs_ext_discount_amt) AS avg_discount, COUNT(DISTINCT t.t_shift) AS distinct_shifts FROM catalog_sales cs JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN date_dim d_start ON cp.cp_start_date_sk = d_start.d_date_sk JOIN date_dim d_end ON cp.cp_end_date_sk = d_end.d_date_sk JOIN time_dim t ON cs.cs_sold_time_sk = t.t_time_sk GROUP BY cp.cp_department, cp.cp_catalog_page_id) SELECT department, catalog_page_id, start_date, end_date, total_sales, total_profit, avg_discount, distinct_shifts, CASE WHEN total_profit / NULLIF(total_sales,0) > 0.2 THEN 'High Profit Margin' WHEN total_profit / NULLIF(total_sales,0) > 0.1 THEN 'Medium Profit Margin' ELSE 'Low Profit Margin' END AS profit_margin_category, RANK() OVER (PARTITION BY department ORDER BY total_profit DESC) AS dept_page_rank, DENSE_RANK() OVER (ORDER BY total_profit DESC) AS overall_page_rank FROM page_sales ORDER BY department, dept_page_rank
